 70	async function getFirstWorkDirFromDoJournal(journalPath: string): Promise<string | null> {
 71	  try {
 72	    const content = await fs.promises.readFile(journalPath, "utf-8");
 73	    const firstLine = content.split("\n").find(l => l.trim().length > 0);
 74	    if (!firstLine) return null;
 75	    const entry = JSON.parse(firstLine);
 76	    // Do session journal entries have a work_dir field in the session_start event
 77	    if (entry.type === "session_start" && entry.work_dir) {
 78	      return entry.work_dir;
 79	    }
 80	    // Fallback: extract work_dir from metadata
 81	    return entry.work_dir || entry.metadata?.work_dir || null;
 82	  } catch {
 83	    return null;
 84	  }
 85	}
