146	  [Methods.GetAllConsiliumSessions]: async (_, ctx) => {
147	    if (!ctx.workspaceRoot) return [];
148	
149	    // The SDK hashes workDir case-sensitively. On Windows the same folder can
150	    // appear under c:\ and C:\ hashes. Query every registered variant.
151	    const registered = getRegisteredWorkDirs(ctx.workspaceRoot);
152	    const allSessions: SessionInfo[] = [];
153	    const seen = new Set<string>();
154	
155	    // Scan Do sessions FIRST so they take priority over SDK regular sessions
156	    // that share the same UUID (Do sessions stored in workspace-local do dir
157	    // also appear as regular SDK sessions in ~/.consilium/sessions/{hash}/).
158	    const doSessions = await listDoSessions(registered);
159	    for (const ds of doSessions) {
160	      if (!seen.has(ds.id)) {
161	        seen.add(ds.id);
162	        const meta = ctx.getSessionMetadata(ds.id);
163	        ds.brief = meta?.title || ds.brief;
164	        (ds as any).mode = meta?.mode || 'do';
165	        allSessions.push(ds);
166	      }
167	    }
168	
169	    // Also scan workspace-local Think dirs
170	    for (const wd of registered) {
171	      const thinkDir = getWorkspaceThinkDir(wd);
172	      if (!fs.existsSync(thinkDir)) continue;
173	      const entries = await fs.promises.readdir(thinkDir, { withFileTypes: true });
174	      for (const e of entries) {
175	        if (!e.isDirectory() && e.name.endsWith(".jsonl")) {
176	          const id = e.name.slice(0, -".jsonl".length);
177	          if (!UUID_REGEX.test(id) || seen.has(id)) continue;
178	          seen.add(id);
179	          const filePath = path.join(thinkDir, e.name);
180	          const st = await fs.promises.stat(filePath);
181	          const brief = (await getFirstUserMessageFromThinkFile(filePath)) || DEFAULT_FALLBACK_TITLE;
182	          allSessions.push({
183	            id,
184	            workDir: '[Think]',
185	            updatedAt: st.mtimeMs || st.mtime.getTime(),
186	            contextFile: filePath,
187	            brief,
188	            isThinking: true,
189	            mode: 'think',
190	          } as any);
191	        }
192	      }
193	    }
194	
195	    // Then SDK regular sessions (remaining UUIDs not already claimed)
196	    for (const dir of registered) {
197	      try {
198	        const sess = await listSessions(dir);
199	        for (const s of sess) {
200	          if (!seen.has(s.id)) {
201	            seen.add(s.id);
202	            const meta = ctx.getSessionMetadata(s.id);
203	            s.brief = meta?.title || s.brief;
204	            (s as any).mode = meta?.mode || 'legacy';
205	            allSessions.push(s);
206	          }
207	        }
208	      } catch {
209	        // ignore missing directories
210	      }
211	    }
212	
213	    return allSessions.sort((a, b) => b.updatedAt - a.updatedAt);
214	  },
