293	  [Methods.LoadConsiliumSessionHistory]: async (params: LoadHistoryParams, ctx): Promise<StreamEvent[]> => {
294	    if (!UUID_REGEX.test(params.consiliumSessionId)) {
295	      return [];
296	    }
297	
298	    // Resolve the Think session file: check workspace-local paths first, then
299	    // fall back to legacy global path (for pre-Phase 09 sessions).
300	    let thinkFile: string | null = null;
301	    let isThinkFile = false;
302	
303	    // 1. Search workspace-local paths
304	    const candidateDirs = new Set<string>();
305	    if (params.workDir) candidateDirs.add(params.workDir);
306	    if (ctx.workDir) candidateDirs.add(ctx.workDir);
307	    if (ctx.workspaceRoot) {
308	      for (const dir of getRegisteredWorkDirs(ctx.workspaceRoot)) {
309	        candidateDirs.add(dir);
310	      }
311	    }
312	    for (const dir of candidateDirs) {
313	      const wsFile = path.join(getWorkspaceThinkDir(dir), `${params.consiliumSessionId}.jsonl`);
314	      if (fs.existsSync(wsFile)) {
315	        thinkFile = wsFile;
316	        isThinkFile = true;
317	        break;
318	      }
319	    }
320	
321	    // 2. Fall back to legacy global path (pre-Phase 09 sessions)
322	    if (!isThinkFile) {
323	      const legacyFile = path.join(getThinkDir(), `${params.consiliumSessionId}.jsonl`);
324	      if (fs.existsSync(legacyFile)) {
325	        thinkFile = legacyFile;
326	        isThinkFile = true;
327	      }
328	    }
329	
330	    // Think sessions can be loaded without a workspace; Do sessions require one.
331	    if (!isThinkFile && !ctx.workDir) {
332	      return [];
333	    }
334	
335	    const fileKey = ctx.getFileManagerKey();
336	    ctx.fileManager.setSessionId(fileKey, params.consiliumSessionId);
337	    if (ctx.workDir) {
338	      BaselineManager.initSession(ctx.workDir, params.consiliumSessionId);
339	    }
340	
341	    // ---- Think session path (base history) ----
342	    const thinkEvents: StreamEvent[] = [];
343	    if (isThinkFile && thinkFile) {
344	      const lines = (await fs.promises.readFile(thinkFile, "utf-8"))
345	        .split("\n")
346	        .filter((l) => l.trim());
347	      for (const line of lines) {
348	        try {
349	          const entry = JSON.parse(line);
350	          if (entry.role === "user" || entry.role === "assistant") {
351	            thinkEvents.push({
352	              type: "Message",
353	              payload: { role: entry.role, content: entry.content },
354	              _sessionId: params.consiliumSessionId,
355	              mode: 'think',
356	            } as any);
357	          }
358	        } catch {
359	          // ignore malformed lines
360	        }
361	      }
362	    }
363	
364	    const meta = ctx.getSessionMetadata(params.consiliumSessionId);
365	    // If a think file exists and the stored mode is not explicitly 'do', treat it as a Think session.
366	    // This protects against lost globalState after extension reinstall.
367	    const mode = meta?.mode || (isThinkFile ? 'think' : 'legacy');
368	    const resolvedMode: 'think' | 'do' = mode === 'do' ? 'do' : 'think';
369	
370	    if (resolvedMode === 'think') {
371	      // Force terminal event so Think tab doesn't get stuck
372	      thinkEvents.push({
373	        type: "history_restored",
374	        result: { status: "restored" },
375	        _sessionId: params.consiliumSessionId,
376	        mode: 'think',
377	      } as any);
378	      return thinkEvents;
379	    }
380	
381	    // ---- Regular Do session path ----
382	    // Prefer the workDir supplied by the caller; fall back to registered
383	    // variants to handle Windows case-sensitivity differences.
384	    let doEvents: StreamEvent[] = [];
385	    const candidateWorkDirs = new Set<string>();
386	    if (params.workDir) candidateWorkDirs.add(params.workDir);
387	    if (ctx.workDir) candidateWorkDirs.add(ctx.workDir);
388	    if (ctx.workspaceRoot) {
389	      for (const dir of getRegisteredWorkDirs(ctx.workspaceRoot)) {
390	        candidateWorkDirs.add(dir);
391	      }
392	    }
393	    if (candidateWorkDirs.size === 0) {
394	      return [];
395	    }
396	    for (const dir of candidateWorkDirs) {
397	      try {
398	        const events = await parseSessionEvents(dir, params.consiliumSessionId);
399	        if (events.length > 0) {
400	          doEvents = events;
401	          break;
402	        }
403	      } catch {
404	        // try next candidate
405	      }
406	    }
407	
408	    const events = [
409	      ...thinkEvents,
410	      ...doEvents.map((e) => ({ ...e, _sessionId: params.consiliumSessionId, mode: 'do' as const }) as any),
411	    ];
412	
413	    // If the previous CLI process was killed (window reload), wire.jsonl ends
414	    // mid-stream. The webview would stay stuck in isProcessing=true.
415	    // Append a history_restored event to unlock the UI.
416	    if (!ctx.getTurn()) {
417	      const last = events[events.length - 1] as any;
418	      const isTerminal =
419	        last &&
420	        (last.type === "stream_complete" ||
421	          last.type === "stream_aborted" ||
422	          last.type === "history_restored" ||
423	          last.type === "error" ||
424	          last.type === "turn_complete" ||
425	          last.type === "done");
426	      if (!isTerminal) {
427	        events.push({
428	          type: "history_restored",
429	          result: { status: "restored" },
430	          _sessionId: params.consiliumSessionId,
431	          mode: 'do',
432	        } as any);
433	      }
434	    }
435	
436	    return events;
437	  },
