439	  [Methods.DeleteConsiliumSession]: async (params: DeleteSessionParams, ctx): Promise<{ ok: boolean }> => {
440	    if (!ctx.workDir || !UUID_REGEX.test(params.sessionId)) {
441	      return { ok: false };
442	    }
443	    return { ok: await deleteSession(ctx.workDir, params.sessionId) };
