446	  [Methods.ForkConsiliumSession]: async (params: ForkSessionParams, ctx): Promise<ForkSessionResult | null> => {
447	    if (!ctx.workDir || !UUID_REGEX.test(params.sessionId) || params.turnIndex < 0) {
448	      return null;
449	    }
450	    try {
451	      return await forkSession({
452	        workDir: ctx.workDir,
453	        sourceSessionId: params.sessionId,
454	        turnIndex: params.turnIndex,
455	      });
456	    } catch (err) {
457	      handlerLog.error("Fork session failed", { error: String(err) });
458	      return null;
459	    }
460	  },
