462	  [Methods.WriteSessionMetadata]: async (params: WriteSessionMetadataParams, ctx) => {
463	    const { sessionId, title, source } = params;
464	    const meta = ctx.getSessionMetadata(sessionId) ?? {};
465	    ctx.setSessionMetadata(sessionId, {
466	      ...meta,
467	      title,
468	      titleSource: source,
469	      titleGeneratedAt: source === "llm" ? Date.now() : meta.titleGeneratedAt,
470	    });
471	    ctx.broadcast(
472	      Events.SessionTitleUpdated,
473	      { sessionId, title, source },
474	      ctx.webviewId,
475	    );
476	    return { ok: true };
477	  },
