483	  [Methods.CheckProjectSetup]: async (_, ctx) => {
484	    const workDir = ctx.workDir || ctx.workspaceRoot;
485	    if (!workDir) {
486	      return { initialized: false };
487	    }
488	    const consiliumDir = path.join(workDir, '.consilium');
489	    const sessionsDir = path.join(consiliumDir, 'sessions');
490	    const agentsDir = path.join(consiliumDir, 'agents');
491	
492	    const initialized =
493	      fs.existsSync(consiliumDir) &&
494	      fs.existsSync(sessionsDir) &&
495	      fs.existsSync(agentsDir);
496	
497	    return { initialized };
498	  },
499	
500	  [Methods.InitializeProject]: async (_, ctx) => {
501	    const workDir = ctx.workDir || ctx.workspaceRoot;
502	    if (!workDir) {
503	      return { success: false, error: 'No workspace' };
504	    }
505	
506	    try {
507	      const consiliumDir = path.join(workDir, '.consilium');
508	      fs.mkdirSync(path.join(consiliumDir, 'sessions', 'think'), { recursive: true });
509	      fs.mkdirSync(path.join(consiliumDir, 'sessions', 'do'), { recursive: true });
510	      fs.mkdirSync(path.join(consiliumDir, 'sessions', 'regular'), { recursive: true });
511	      fs.mkdirSync(path.join(consiliumDir, 'agents'), { recursive: true });
512	      return { success: true };
513	    } catch (err) {
514	      return { success: false, error: String(err) };
515	    }
516	  },
517	};

